files.unformatted.hcl:
schema "main" {
    name = "main"
}
table "users" {
    schema = schema.main
    column "id" { type = int }
}

files.complex.hcl:
schema "public" {comment="public schema"}
table "users" {
schema=schema.public
column "id" {type=int null=false}
column "tags" {type=list(varchar(50))}
primary_key {columns=[column.id]}
index "idx_tags" {columns=[column.tags]}
}

files.relationships.hcl:
table "users" {schema=schema.public
column "id" {type=int}
}
table "posts" {schema=schema.public
column "id" {type=int}
column "user_id" {type=int}
foreign_key "fk_user" {columns=[column.user_id] ref_columns=[table.users.column.id]}
}

